 62→// ListSessions returns all sessions from the entire/checkpoints/v1 branch,
 63→// plus any additional sessions from strategies implementing SessionSource.
 64→// It automatically discovers all registered strategies and merges their sessions.
 65→func ListSessions() ([]Session, error) {
 66→	repo, err := OpenRepository()
 67→	if err != nil {
 68→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 69→	}
 70→
 71→	// Get checkpoints from the entire/checkpoints/v1 branch
 72→	checkpoints, err := ListCheckpoints()
 73→	if err != nil {
 74→		return nil, fmt.Errorf("failed to list checkpoints: %w", err)
 75→	}
 76→
 77→	// Group checkpoints by session ID
 78→	// For multi-session checkpoints, expand SessionIDs array so each session gets the checkpoint
 79→	sessionMap := make(map[string]*Session)
 80→	for _, cp := range checkpoints {
 81→		// Determine which session IDs this checkpoint belongs to
 82→		// Multi-session checkpoints have SessionIDs populated; single-session use SessionID
 83→		sessionIDs := cp.SessionIDs
 84→		if len(sessionIDs) == 0 {
 85→			sessionIDs = []string{cp.SessionID}
 86→		}
 87→
 88→		for _, sessionID := range sessionIDs {
 89→			if sessionID == "" {
 90→				continue
 91→			}
 92→
 93→			if existing, ok := sessionMap[sessionID]; ok {
 94→				existing.Checkpoints = append(existing.Checkpoints, Checkpoint{
 95→					CheckpointID:     cp.CheckpointID,
 96→					Message:          "Checkpoint: " + cp.CheckpointID.String(),
 97→					Timestamp:        cp.CreatedAt,
 98→					IsTaskCheckpoint: cp.IsTask,
 99→					ToolUseID:        cp.ToolUseID,
100→				})
101→			} else {
102→				// Get description from the checkpoint tree
103→				description := getDescriptionForCheckpoint(repo, cp.CheckpointID)
104→
105→				sessionMap[sessionID] = &Session{
106→					ID:          sessionID,
107→					Description: description,
108→					Strategy:    "", // Will be set from metadata if available
109→					StartTime:   cp.CreatedAt,
110→					Checkpoints: []Checkpoint{{
111→						CheckpointID:     cp.CheckpointID,
112→						Message:          "Checkpoint: " + cp.CheckpointID.String(),
113→						Timestamp:        cp.CreatedAt,
114→						IsTaskCheckpoint: cp.IsTask,
115→						ToolUseID:        cp.ToolUseID,
116→					}},
117→				}
118→			}
119→		}
120→	}
121→
122→	// Check all registered strategies for additional sessions
123→	for _, name := range List() {
124→		strat, stratErr := Get(name)
125→		if stratErr != nil {
126→			continue
127→		}
128→		source, ok := strat.(SessionSource)
129→		if !ok {
130→			continue
131→		}
132→		additionalSessions, addErr := source.GetAdditionalSessions()
133→		if addErr != nil {
134→			continue // Skip strategies that fail to provide additional sessions
135→		}
136→		for _, addSession := range additionalSessions {
137→			if addSession == nil {
138→				continue
139→			}
140→			if existing, ok := sessionMap[addSession.ID]; ok {
141→				// Merge checkpoints - deduplicate by CheckpointID
142→				existingCPIDs := make(map[string]bool)
143→				for _, cp := range existing.Checkpoints {
144→					existingCPIDs[cp.CheckpointID.String()] = true
145→				}
146→				for _, cp := range addSession.Checkpoints {
147→					if !existingCPIDs[cp.CheckpointID.String()] {
148→						existing.Checkpoints = append(existing.Checkpoints, cp)
149→					}
150→				}
151→				// Update start time if additional session is older
152→				if addSession.StartTime.Before(existing.StartTime) {
153→					existing.StartTime = addSession.StartTime
154→				}
155→				// Use description from additional source if existing is empty
156→				if existing.Description == "" || existing.Description == NoDescription {
157→					existing.Description = addSession.Description
158→				}
159→			} else {
160→				// New session from additional source
161→				sessionMap[addSession.ID] = addSession
162→			}
163→		}
164→	}
165→
166→	// Convert map to slice
167→	sessions := make([]Session, 0, len(sessionMap))
168→	for _, session := range sessionMap {
169→		// Sort checkpoints within each session by timestamp (most recent first)
170→		sort.Slice(session.Checkpoints, func(i, j int) bool {
171→			return session.Checkpoints[i].Timestamp.After(session.Checkpoints[j].Timestamp)
172→		})
173→		sessions = append(sessions, *session)
174→	}
175→
176→	// Sort sessions by start time (most recent first)
177→	sort.Slice(sessions, func(i, j int) bool {
178→		return sessions[i].StartTime.After(sessions[j].StartTime)
179→	})
180→
181→	return sessions, nil
182→}
183→
184→// GetSession finds a session by ID (supports prefix matching).
185→// Returns ErrNoSession if no matching session is found.
186→func GetSession(sessionID string) (*Session, error) {
187→	sessions, err := ListSessions()
188→	if err != nil {
189→		return nil, err
190→	}
191→	return findSessionByID(sessions, sessionID)
192→}
