194→// getDescriptionForCheckpoint reads the description for a checkpoint from the entire/checkpoints/v1 branch.
195→// It reads from the latest session subdirectory in the new storage format.
196→func getDescriptionForCheckpoint(repo *git.Repository, checkpointID id.CheckpointID) string {
197→	tree, err := GetMetadataBranchTree(repo)
198→	if err != nil {
199→		return NoDescription
200→	}
201→
202→	// Get the checkpoint tree
203→	checkpointTree, err := tree.Tree(checkpointID.Path())
204→	if err != nil {
205→		return NoDescription
206→	}
207→
208→	// Read root metadata.json to get session count and sessions map
209→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
210→	if err != nil {
211→		return NoDescription
212→	}
213→
214→	content, err := metadataFile.Contents()
215→	if err != nil {
216→		return NoDescription
217→	}
218→
219→	var summary checkpoint.CheckpointSummary
220→	if err := json.Unmarshal([]byte(content), &summary); err != nil {
221→		return NoDescription
222→	}
223→
224→	// Find the first session's prompt/context path
225→	// Try to use the latest session for description (0-based indexing)
226→	sessionDir := "0"
227→	if len(summary.Sessions) > 0 {
228→		sessionDir = strconv.Itoa(len(summary.Sessions) - 1) // Use latest session
229→	}
230→
231→	sessionTree, err := checkpointTree.Tree(sessionDir)
232→	if err != nil {
233→		return NoDescription
234→	}
235→
236→	return getSessionDescriptionFromTree(sessionTree, "")
237→}
238→
239→// findSessionByID finds a session by exact ID or prefix match.
240→func findSessionByID(sessions []Session, sessionID string) (*Session, error) {
241→	for _, session := range sessions {
242→		if session.ID == sessionID || strings.HasPrefix(session.ID, sessionID) {
243→			return &session, nil
244→		}
245→	}
246→	return nil, ErrNoSession
247→}
