294→// FindCheckpointUUID finds the UUID of the message containing the tool_result
295→// for the given tool_use_id. This is used to find the checkpoint point for
296→// transcript truncation when rewinding to a task.
297→// Returns the UUID and true if found, empty string and false otherwise.
298→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
299→	for _, line := range transcript {
300→		if line.Type != transcriptTypeUser {
301→			continue
302→		}
303→
304→		var msg userMessageWithToolResults
305→		if err := json.Unmarshal(line.Message, &msg); err != nil {
306→			continue
307→		}
308→
309→		for _, block := range msg.Content {
310→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
311→				return line.UUID, true
312→			}
313→		}
314→	}
315→	return "", false
316→}
