318→// TruncateTranscriptAtUUID returns transcript lines up to and including the
319→// line with the given UUID. If the UUID is not found or is empty, returns
320→// the entire transcript.
321→//
322→//nolint:revive // Exported for testing purposes
323→func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
324→	if uuid == "" {
325→		return transcript
326→	}
327→
328→	for i, line := range transcript {
329→		if line.UUID == uuid {
330→			return transcript[:i+1]
331→		}
332→	}
333→
334→	// UUID not found, return full transcript
335→	return transcript
336→}
