338→// writeTranscript writes transcript lines to a file in JSONL format.
339→func writeTranscript(path string, transcript []transcriptLine) error {
340→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
341→	if err != nil {
342→		return fmt.Errorf("failed to create file: %w", err)
343→	}
344→	defer func() { _ = file.Close() }()
345→
346→	for _, line := range transcript {
347→		data, err := json.Marshal(line)
348→		if err != nil {
349→			return fmt.Errorf("failed to marshal line: %w", err)
350→		}
351→		if _, err := file.Write(data); err != nil {
352→			return fmt.Errorf("failed to write line: %w", err)
353→		}
354→		if _, err := file.WriteString("\n"); err != nil {
355→			return fmt.Errorf("failed to write newline: %w", err)
356→		}
357→	}
358→
359→	return nil
360→}
