368→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
369→// Returns empty position if file doesn't exist or is empty.
370→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
371→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
372→	if path == "" {
373→		return TranscriptPosition{}, nil
374→	}
375→
376→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
377→	if err != nil {
378→		if os.IsNotExist(err) {
379→			return TranscriptPosition{}, nil
380→		}
381→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
382→	}
383→	defer func() { _ = file.Close() }()
384→
385→	var pos TranscriptPosition
386→	reader := bufio.NewReader(file)
387→
388→	for {
389→		lineBytes, err := reader.ReadBytes('\n')
390→		if err != nil && err != io.EOF {
391→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
392→		}
393→
394→		if len(lineBytes) == 0 {
395→			if err == io.EOF {
396→				break
397→			}
398→			continue
399→		}
400→
401→		pos.LineCount++
402→
403→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
404→		var line transcriptLine
405→		if err := json.Unmarshal(lineBytes, &line); err == nil {
406→			if line.UUID != "" {
407→				pos.LastUUID = line.UUID
408→			}
409→		}
410→
411→		if err == io.EOF {
412→			break
413→		}
414→	}
415→
416→	return pos, nil
417→}
